#include <bits/stdc++.h>
using namespace std;

/**
 * Variant 5: Using adjacency list, with a different matching implementation
 */

int maxMatching(const vector<vector<int>>& g) {
    int n = g.size();
    vector<int> match(n, -1);
    int result = 0;

    function<bool(int, vector<bool>&)> dfs = [&](int u, vector<bool>& visited) {
        for (int v : g[u]) {
            if (!visited[v]) {
                visited[v] = true;
                if (match[v] == -1 || dfs(match[v], visited)) {
                    match[v] = u;
                    match[u] = v;
                    return true;
                }
            }
        }
        return false;
    };

    for (int u = 0; u < n; u++) {
        vector<bool> visited(n, false);
        if (dfs(u, visited))
            result++;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    if (n > m) {
        swap(n, m);
    }
    long long totalCells = (long long)n * m;
    if (totalCells < 100) {
        vector<vector<int>> graph((int)totalCells);
        for (int i = 0; i < (int)totalCells; i++) {
            for (int j = 0; j < (int)totalCells; j++) {
                int r1 = i / m;
                int c1 = i % m;
                int r2 = j / m;
                int c2 = j % m;
                if (abs(r1 - r2) + abs(c1 - c2) == 3) {
                    graph[i].push_back(j);
                }
            }
        }
        int matchCount = maxMatching(graph);
        cout << matchCount * 2 << "\n";
    } else {
        long long res;
        if (n == 1) {
            res = (m / 6) * 6 + ((m % 6 == 4) ? 2 : 0) + ((m % 6 == 5) ? 4 : 0);
        } else {
            res = (long long)n * m;
            res -= res % 2;
        }
        cout << res << "\n";
    }
    return 0;
}

